mapper.select:
-- 사용자가 신청한 정책 현황 조회 SELECT CONCAT('policy_', up.user_policy_id) AS applicationId, up.status AS processStage, '정책' AS productType, p.policy_name AS productName, p.supervising_organization_name AS providerName, (SELECT COUNT(DISTINCT rd.document_id) FROM required_documents rd JOIN user_documents ud ON rd.document_id = ud.document_id WHERE rd.policy_id = up.policy_id AND ud.user_id = up.user_id) AS completedDocsCount, (SELECT COUNT(*) FROM required_documents WHERE policy_id = up.policy_id) AS totalDocsCount FROM user_policies up JOIN policies p ON up.policy_id = p.policy_id WHERE up.user_id = #{userId}
UNION ALL
-- 사용자가 신청한 대출 현황 조회 SELECT CONCAT('loan_', ul.user_loan_id) AS applicationId, ul.status AS processStage, '대출' AS productType, l.product_name AS productName, l.company_name AS providerName, (SELECT COUNT(DISTINCT rd.document_id) FROM required_documents rd JOIN user_documents ud ON rd.document_id = ud.document_id WHERE rd.loan_id = ul.loan_id AND ud.user_id = ul.user_id) AS completedDocsCount, (SELECT COUNT(*) FROM required_documents WHERE loan_id = ul.loan_id) AS totalDocsCount FROM user_loans ul JOIN loans l ON ul.loan_id = l.loan_id WHERE ul.user_id = #{userId}

mapper.update:
UPDATE user_policies
SET status = #{status}
WHERE user_id = #{userId} AND user_policy_id = #{id}

UPDATE user_loans
SET status = #{status}
WHERE user_id = #{userId} AND user_loan_id = #{id}
